package com.gestordevendas.api.food; import jakarta.persistence.*; import java.math.BigDecimal; @Embeddable public class SnackAdditional { @Column(name="name",nullable=false) private String name; @Column(name="price",nullable=false) private BigDecimal price; protected SnackAdditional(){} public SnackAdditional(String n, BigDecimal p){name=n;price=p;} public String getName(){return name;} public BigDecimal getPrice(){return price;} }